const crypto = require('crypto');
const secret = process.env.N8N_WEBHOOK_HMAC_SECRET;
if (!secret) {
  throw new Error('N8N_WEBHOOK_HMAC_SECRET environment variable is not configured');
}
const timestamp = String(Date.now());
const signature = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.GET:/api/n8n/overdue-loans`)
  .digest('hex');

return [{ json: { timestamp, signature } }];

const crypto = require('crypto');
const secret = process.env.N8N_WEBHOOK_HMAC_SECRET;
const response = $input.first().json;
const loans = response.loans || [];
const dateStr = response.date || new Date().toISOString().slice(0, 10);

return loans.map((loan) => {
  const idempotencyKey = `overdue:${loan.loanId}:${dateStr}`;
  const callbackPayload = JSON.stringify({
    loanId: loan.loanId,
    idempotencyKey,
    summary: `Overdue reminder sent for ${loan.toolName} (due ${loan.endDate})`
  });
  const timestamp = String(Date.now());
  const signature = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${callbackPayload}`)
    .digest('hex');

  return {
    json: {
      loanId: loan.loanId,
      borrowerEmail: loan.borrowerEmail,
      borrowerName: loan.borrowerName,
      toolName: loan.toolName,
      endDate: loan.endDate,
      lenderName: loan.lenderName,
      callbackPayload,
      timestamp,
      signature
    }
  };
});

